declare(strict_types=1);require_once dirname(__DIR__,2).'/bootstrap.php';ensure_v16_schema(db());$id=(int)($_GET['clip_id']??0);v17_content('clip',$id,current_user());if($id<1)json_response(['comments'=>[]]);
try{$st=db()->prepare('SELECT c.*,u.public_id,u.username,u.display_name,u.avatar_url FROM clip_comments c JOIN users u ON u.id=c.user_id WHERE c.clip_id=? ORDER BY c.id ASC LIMIT 200');$st->execute([$id]);json_response(['comments'=>array_map(static fn($r)=>['id'=>(int)$r['id'],'parentCommentId'=>$r['parent_comment_id']?(int)$r['parent_comment_id']:null,'body'=>(string)$r['body'],'createdAt'=>(string)$r['created_at'],'user'=>['id'=>(int)$r['user_id'],'publicId'=>(string)($r['public_id']??''),'username'=>(string)$r['username'],'displayName'=>(string)$r['display_name'],'avatarUrl'=>$r['avatar_url']?:null]],$st->fetchAll())]);}catch(Throwable $e){json_response(['message'=>'Yorumlar alınamadı.'],500);}
